contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy == dummy);

        bool reverted1;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }

        bool reverted2;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }

        assert(!reverted1 && !reverted2);
    }

    receive() external payable {}
}

