pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        bool reverted1;
        try c.Initialized() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        bool reverted2;
        try c.Initialized() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        assertTrue(!reverted1 && !reverted2);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
